  "dados_desfecho_incompletos": {
    "julgamento": "Low",
    "justificativa": "O estudo realizou uma análise de intenção de tratar modificada e contabilizou os pacientes que não receberam a intervenção devido a retiradas de consentimento ou cancelamentos."
  },
  "relato_seletivo": {
    "julgamento": "Low",
    "justificativa": "O estudo reporta tanto o desfecho primário (complicações em 30 dias) quanto diversos desfechos secundários e parâmetros fisiológicos."
  },
  "outros_vieses": {
    "julgamento": "Low",
    "justificativa": "Não há informações que indiquem fontes de financiamento ou conflitos de interesse que possam introduzir vieses sistemáticos."
  },
  "risco_global": {
    "julgamento": "Low",
    "justificativa": "O estudo apresenta um desenho de RCT robusto com randomização, ocultação de alocação e cegamento da equipe de avaliação, apesar da impossibilidade de cegar o anestesiologista."
